using System.Data;using Microsoft.Data.SqlClient;using Karaoke.DTO;namespace Karaoke.DAL;public class KaraokeRepository{public DataTable Rooms(){using var c=Db.Open();using var da=new SqlDataAdapter("SELECT MaPhong,TenPhong,LoaiPhong,GiaTheoGio,TrangThai FROM PhongHat ORDER BY MaPhong",c);var t=new DataTable();da.Fill(t);return t;}public DataTable Services(){using var c=Db.Open();using var da=new SqlDataAdapter("SELECT MaDV,TenDV,DonGia,TonKho FROM DichVu",c);var t=new DataTable();da.Fill(t);return t;}public DataTable ActiveBills(){using var c=Db.Open();using var da=new SqlDataAdapter("SELECT h.MaHD,h.MaPhong,p.TenPhong,h.GioVao FROM HoaDon h JOIN PhongHat p ON p.MaPhong=h.MaPhong WHERE h.TrangThai=0",c);var t=new DataTable();da.Fill(t);return t;}public int OpenRoom(int room){using var c=Db.Open();using var tx=c.BeginTransaction();try{using(var chk=new SqlCommand("UPDATE PhongHat SET TrangThai=N'Đang hát' WHERE MaPhong=@id AND TrangThai=N'Trống'",c,tx)){chk.Parameters.AddWithValue("@id",room);if(chk.ExecuteNonQuery()!=1)throw new Exception("Phòng không trống hoặc không tồn tại.");}int id;using(var cmd=new SqlCommand("INSERT HoaDon(MaPhong,GioVao) VALUES(@id,GETDATE()); SELECT CAST(SCOPE_IDENTITY() AS int)",c,tx)){cmd.Parameters.AddWithValue("@id",room);id=(int)cmd.ExecuteScalar()!;}tx.Commit();return id;}catch{tx.Rollback();throw;}}public DataTable BillServices(int bill){using var c=Db.Open();using var da=new SqlDataAdapter("SELECT ct.MaDV,d.TenDV,ct.SoLuong,ct.DonGia,ct.SoLuong*ct.DonGia AS ThanhTien FROM ChiTietDichVu ct JOIN DichVu d ON d.MaDV=ct.MaDV WHERE ct.MaHD=@id",c);da.SelectCommand!.Parameters.AddWithValue("@id",bill);var t=new DataTable();da.Fill(t);return t;}public void AddServices(int bill,List<ServiceItem> items){using var c=Db.Open();using var tx=c.BeginTransaction();try{foreach(var x in items){decimal price;using(var p=new SqlCommand("SELECT DonGia FROM DichVu WHERE MaDV=@id",c,tx)){p.Parameters.AddWithValue("@id",x.MaDV);price=Convert.ToDecimal(p.ExecuteScalar()??throw new Exception("Không tìm thấy dịch vụ."));}using(var up=new SqlCommand("IF EXISTS(SELECT 1 FROM ChiTietDichVu WHERE MaHD=@h AND MaDV=@d) UPDATE ChiTietDichVu SET SoLuong=SoLuong+@q WHERE MaHD=@h AND MaDV=@d ELSE INSERT ChiTietDichVu(MaHD,MaDV,SoLuong,DonGia) VALUES(@h,@d,@q,@p)",c,tx)){up.Parameters.AddWithValue("@h",bill);up.Parameters.AddWithValue("@d",x.MaDV);up.Parameters.AddWithValue("@q",x.SoLuong);up.Parameters.AddWithValue("@p",price);up.ExecuteNonQuery();}}tx.Commit();}catch{tx.Rollback();throw;}}public void Pay(int bill){using var c=Db.Open();using var tx=c.BeginTransaction();try{int room;DateTime start;using(var q=new SqlCommand("SELECT MaPhong,GioVao FROM HoaDon WHERE MaHD=@id AND TrangThai=0",c,tx)){q.Parameters.AddWithValue("@id",bill);using var r=q.ExecuteReader();if(!r.Read())throw new Exception("Hóa đơn không tồn tại hoặc đã thanh toán.");room=r.GetInt32(0);start=r.GetDateTime(1);}decimal roomPrice;using(var q=new SqlCommand("SELECT GiaTheoGio FROM PhongHat WHERE MaPhong=@id",c,tx)){q.Parameters.AddWithValue("@id",room);roomPrice=Convert.ToDecimal(q.ExecuteScalar());}decimal hours=(decimal)Math.Max(0.01,(DateTime.Now-start).TotalHours);decimal serviceTotal;using(var q=new SqlCommand("SELECT ISNULL(SUM(SoLuong*DonGia),0) FROM ChiTietDichVu WHERE MaHD=@id",c,tx)){q.Parameters.AddWithValue("@id",bill);serviceTotal=Convert.ToDecimal(q.ExecuteScalar());}using(var q=new SqlCommand("UPDATE HoaDon SET GioRa=GETDATE(),TongTienPhong=@p,TongTienDichVu=@s,TrangThai=1 WHERE MaHD=@id",c,tx)){q.Parameters.AddWithValue("@p",Math.Ceiling(hours*roomPrice));q.Parameters.AddWithValue("@s",serviceTotal);q.Parameters.AddWithValue("@id",bill);q.ExecuteNonQuery();}int detailCount;using(var q=new SqlCommand("SELECT COUNT(*) FROM ChiTietDichVu WHERE MaHD=@id",c,tx)){q.Parameters.AddWithValue("@id",bill);detailCount=Convert.ToInt32(q.ExecuteScalar());}int updated;using(var q=new SqlCommand("UPDATE d SET TonKho=d.TonKho-ct.SoLuong FROM DichVu d JOIN ChiTietDichVu ct ON ct.MaDV=d.MaDV WHERE ct.MaHD=@id AND d.TonKho>=ct.SoLuong",c,tx)){q.Parameters.AddWithValue("@id",bill);updated=q.ExecuteNonQuery();}if(updated!=detailCount)throw new Exception("Tồn kho dịch vụ không đủ. Giao dịch đã được hoàn tác.");using(var q=new SqlCommand("UPDATE PhongHat SET TrangThai=N'Trống' WHERE MaPhong=@id",c,tx)){q.Parameters.AddWithValue("@id",room);q.ExecuteNonQuery();}tx.Commit();}catch{tx.Rollback();throw;}}}